const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const stored = (typeof localStorage !== 'undefined' && localStorage.getItem('aladiah_lang')) as Language | null;
  const [language, setLanguage] = useState<Language>(stored || 'en');

  // Sync RTL direction whenever language changes
  useEffect(() => {
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = language;
  }, [language]);

  // Load from Supabase profile on auth
  useEffect(() => {
    // Apply stored language dir immediately on mount
    if (stored) document.documentElement.dir = stored === 'ar' ? 'rtl' : 'ltr';
    supabase.auth.getUser().then(({ data }) => {
      if (!data.user) return;
      supabase.from('profiles').select('preferred_language').eq('user_id', data.user.id).maybeSingle().then(({ data: prof }) => {
        if (prof?.preferred_language) {
          const lang = prof.preferred_language as Language;
          setLanguage(lang);
          localStorage.setItem('aladiah_lang', lang);
        }
      });
    });
  }, []);

  const setLanguagePersisted = async (lang: Language) => {
    setLanguage(lang);
    localStorage.setItem('aladiah_lang', lang);
    const { data } = await supabase.auth.getUser();
    if (data.user) {
      supabase.from('profiles').update({ preferred_language: lang }).eq('user_id', data.user.id).then(() => { });
    }
  };

  const t = (key: string): string => {
    return (translations[language] && translations[language][key])
      || (translations['en'] && translations['en'][key])
      || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage: setLanguagePersisted, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

// =============================================================================
// Translation truth — real UI-string coverage, computed from THIS file.
// Not an estimate: for each language it counts how many of the EN baseline keys
// are actually defined (non-empty), and how many differ from the EN value (a
// proxy for "actually localized" — some legitimately equal EN, e.g. "Scrum").
// Consumed by the Translation Truth Dashboard (/founder/translation).
// =============================================================================
export interface LangCoverage {
  lang: Language;
  name: string;
  total: number;      // EN baseline key count
  present: number;    // keys defined + non-empty in this language
  missing: number;    // EN keys absent/empty here
  localized: number;  // present keys whose value differs from EN (translated proxy)
  pct: number;        // present / total (structural coverage %)
}

export function uiStringCoverage(): LangCoverage[] {
  const en = translations.en || {};
  const enKeys = Object.keys(en);
  const total = enKeys.length;
  return (Object.keys(translations) as Language[]).map((lang) => {
    const tbl = translations[lang] || {};
    let present = 0, localized = 0;
    for (const k of enKeys) {
      const v = tbl[k];
      if (v != null && String(v).trim().length > 0) {
        present++;
        if (String(v) !== String(en[k])) localized++;
      }
    }
    return {
      lang, name: languageNames[lang], total, present,
      missing: total - present, localized,
      pct: total ? Math.round((present / total) * 100) : 0,
    };
  });
}

